# XOR cell value with whether it differs from ANY orthogonal neighbor
def xor_is_edge(grid, r, c):
    is_edge = False
    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            if grid[nr][nc] != grid[r][c]:
                is_edge = True
                break
    return int(grid[r][c]) ^ int(is_edge)

